const triggers={enquiry_received:'New enquiry submitted',quote_sent:'Quote sent',quote_accepted:'Quote accepted',booking_form_received:'Booking form received',booking_fee_due:'Booking fee due',booking_fee_paid:'Booking fee paid',agreement_signed:'Agreement signed',contract_signed:'Contract signed',questionnaire_submitted:'Questionnaire submitted',balance_due:'Balance due',balance_paid:'Balance paid',wedding_date:'Wedding date',wedding_completed:'Wedding completed'};
