const money=p=>new Intl.NumberFormat('en-GB',{style:'currency',currency:'GBP'}).format(p/100);
const pence=v=>Math.round((Number(v)||0)*100);
function empty(title,copy){return `<div class="empty"><span>✦</span><strong>${title}</strong><p>${copy}</p></div>`}
async function loadPackages(){try{[packages,addOns]=await Promise.all([api('/api/studio/packages'),api('/api/studio/add-ons')]);$('#package-list').innerHTML=packages.length?packages.map(p=>`<button class="catalogue-card" data-package="${p.id}"><span class="status ${p.is_active?'live':'off'}">${p.is_active?'Available':'Hidden'}</span><strong>${escapeHtml(p.name)}</strong><p>${escapeHtml(p.short_description||'No description yet')}</p><footer><b>${money(p.price_pence)}</b><small>${money(p.booking_fee_pence)} booking fee · balance ${p.balance_due_days} days before</small></footer></button>`).join(''):empty('Your first package starts here','Add a clear collection couples can confidently choose.');$('#addon-list').innerHTML=addOns.length?addOns.map(a=>`<button class="addon-card" data-addon="${a.id}"><div><strong>${escapeHtml(a.name)}</strong><small>${a.selection_mode==='mandatory'?'Mandatory':'Optional'} · ${a.is_active?'Available':'Hidden'}</small></div><b>${money(a.price_pence)}</b></button>`).join(''):empty('No add-ons yet','Add albums, extra hours or complimentary extras when you are ready.');document.querySelectorAll('[data-package]').forEach(b=>b.onclick=()=>openPackage(packages.find(p=>p.id===b.dataset.package)));document.querySelectorAll('[data-addon]').forEach(b=>b.onclick=()=>openAddon(addOns.find(a=>a.id===b.dataset.addon)))}catch(e){toast(e.message,true)}}
function openPackage(p){$('#package-form').reset();$('#package-id').value=p?.id||'';$('#package-dialog-title').textContent=p?'Edit package':'Add a package';$('#package-name').value=p?.name||'';$('#package-description').value=p?.short_description||'';$('#package-price').value=p?p.price_pence/100:'';$('#package-fee').value=p?p.booking_fee_pence/100:100;$('#package-balance').value=p?.balance_due_days??45;$('#package-information-url').value=p?.information_url||'';$('#package-inclusions').value=(p?.inclusions||[]).join('\n');$('#package-featured').checked=!!p?.is_featured;$('#package-active').checked=p?p.is_active:true;$('#package-error').textContent='';$('#package-dialog').showModal()}
function openAddon(a){$('#addon-form').reset();$('#addon-id').value=a?.id||'';$('#addon-dialog-title').textContent=a?'Edit add-on':'Add an extra';$('#addon-name').value=a?.name||'';$('#addon-description').value=a?.description||'';$('#addon-information-url').value=a?.information_url||'';$('#addon-price').value=a?a.price_pence/100:0;$('#addon-mode').value=a?.selection_mode||'optional';$('#addon-reason').value=a?.mandatory_reason||'';$('#addon-active').checked=a?a.is_active:true;const eligible=new Set(a?.eligible_package_ids||[]);$('#addon-package-eligibility').innerHTML=packages.filter(item=>item.is_active).map(item=>`<label class="check"><input type="checkbox" value="${item.id}" ${eligible.has(item.id)?'checked':''}> ${escapeHtml(item.name)}</label>`).join('')||'<small>Add a package first, or this extra will be available with every package.</small>';toggleReason();$('#addon-error').textContent='';$('#addon-dialog').showModal()}
$('#new-package').onclick=()=>openPackage();$('#new-addon').onclick=()=>openAddon();$('#addon-mode').onchange=toggleReason;function toggleReason(){$('#reason-wrap').classList.toggle('hidden',$('#addon-mode').value!=='mandatory')}
document.querySelectorAll('.close-dialog').forEach(b=>b.onclick=()=>b.closest('dialog').close());
$('#package-form').onsubmit=async e=>{e.preventDefault();const id=$('#package-id').value,data={name:$('#package-name').value,short_description:$('#package-description').value,information_url:$('#package-information-url').value.trim(),price_pence:pence($('#package-price').value),booking_fee_pence:pence($('#package-fee').value),balance_due_days:Number($('#package-balance').value),inclusions:$('#package-inclusions').value.split('\n'),is_featured:$('#package-featured').checked,is_active:$('#package-active').checked,sort_order:packages.length};try{await api(`/api/studio/packages${id?'/'+id:''}`,{method:id?'PATCH':'POST',body:JSON.stringify(data)});$('#package-dialog').close();await loadPackages();dashboard=await api('/api/studio/dashboard');render();toast(id?'Package updated.':'Package added.')}catch(err){$('#package-error').textContent=err.message}};
$('#addon-form').onsubmit=async e=>{e.preventDefault();const id=$('#addon-id').value,data={name:$('#addon-name').value,description:$('#addon-description').value,information_url:$('#addon-information-url').value.trim(),price_pence:pence($('#addon-price').value),selection_mode:$('#addon-mode').value,mandatory_reason:$('#addon-reason').value,eligible_package_ids:[...document.querySelectorAll('#addon-package-eligibility input:checked')].map(item=>item.value),is_active:$('#addon-active').checked,sort_order:addOns.length};try{await api(`/api/studio/add-ons${id?'/'+id:''}`,{method:id?'PATCH':'POST',body:JSON.stringify(data)});$('#addon-dialog').close();await loadPackages();toast(id?'Add-on updated.':'Add-on added.')}catch(err){$('#addon-error').textContent=err.message}};

const modeNames={off:'Disabled',task:'Task only',review:'Review first',automatic:'Automatic'};
async function loadWorkflow(){try{workflows=await api('/api/studio/workflows');if(!workflows.length){await api('/api/studio/workflows',{method:'POST',body:JSON.stringify({name:'Main client journey',description:'Your enquiry-to-wedding workflow.',is_active:false,sort_order:0})});workflows=await api('/api/studio/workflows')}const w=workflows[0];$('#workflow-name').textContent=w.name;$('#workflow-revision').textContent=`Revision ${w.revision} · Draft`;$('#workflow-steps').innerHTML=w.steps.length?w.steps.map((s,i)=>`<button class="timeline-step" data-step-id="${s.id}"><span class="step-number">${i+1}</span><div><small>${escapeHtml(triggers[s.trigger_event])}</small><strong>${escapeHtml(s.name)}</strong><p>${s.timing_direction==='immediately'?'Immediately':`${s.offset_value} ${s.offset_unit} ${s.timing_direction}`} · ${s.action_type==='email'?'Email to couple':'Manual task'}</p></div><em>${escapeHtml(modeNames[s.mode]||'Disabled')}</em></button>`).join(''):empty('Build your first step','Start with a manual reminder or prepare an email. Every new step is disabled.');document.querySelectorAll('[data-step-id]').forEach(b=>b.onclick=()=>openStep(w.steps.find(s=>s.id===b.dataset.stepId)))}catch(e){toast(e.message,true)}}
function openStep(s){$('#step-form').reset();$('#step-id').value=s?.id||'';$('#step-dialog-title').textContent=s?'Edit workflow step':'Add a workflow step';$('#step-trigger').innerHTML=Object.entries(triggers).map(([v,l])=>`<option value="${v}">${l}</option>`).join('');$('#step-name').value=s?.name||'';$('#step-trigger').value=s?.trigger_event||'enquiry_received';$('#step-direction').value=s?.timing_direction||'after';$('#step-offset').value=s?.offset_value??1;$('#step-unit').value=s?.offset_unit||'days';$('#step-action').value=s?.action_type||'manual_task';$('#step-mode').value=s?.mode||'off';$('#step-task').value=s?.task_title||'';$('#step-subject').value=s?.subject||'';$('#step-message').value=s?.message_body||'';toggleStepFields();$('#step-error').textContent='';$('#step-dialog').showModal()}
function toggleStepFields(){const email=$('#step-action').value==='email',instant=$('#step-direction').value==='immediately';$('#task-wrap').classList.toggle('hidden',email);$('#subject-wrap').classList.toggle('hidden',!email);$('#message-wrap').classList.toggle('hidden',!email);$('#offset-wrap').classList.toggle('hidden',instant)}
$('#new-step').onclick=()=>openStep();$('#step-action').onchange=toggleStepFields;$('#step-direction').onchange=toggleStepFields;
$('#step-form').onsubmit=async e=>{e.preventDefault();const w=workflows[0],id=$('#step-id').value,mode=$('#step-mode').value,data={name:$('#step-name').value,trigger_event:$('#step-trigger').value,timing_direction:$('#step-direction').value,offset_value:$('#step-direction').value==='immediately'?0:Number($('#step-offset').value),offset_unit:$('#step-unit').value,action_type:$('#step-action').value,subject:$('#step-subject').value,message_body:$('#step-message').value,task_title:$('#step-task').value,is_paused:mode==='off',sort_order:w.steps.length};try{const saved=await api(`/api/studio/workflows/${w.id}/steps${id?'/'+id:''}`,{method:id?'PATCH':'POST',body:JSON.stringify(data)});await api(`/api/studio/workflow-steps/${saved.id}/mode`,{method:'PUT',body:JSON.stringify({mode,apply_to_existing:false})});$('#step-dialog').close();await loadWorkflow();dashboard=await api('/api/studio/dashboard');render();toast(id?'Workflow step updated.':'Workflow step added safely.')}catch(err){$('#step-error').textContent=err.message}};

const questionTypeNames={short_text:'Short answer',long_text:'Long answer',email:'Email address',phone:'Telephone number',date:'Date',single_choice:'Choose one',multiple_choice:'Choose several',yes_no:'Yes or no',venue:'Venue search'};
function renderQuestions(){const rows=enquiryForm.questions||[];$('#question-list').innerHTML=rows.length?rows.map((q,index)=>`<button class="question-row" data-question-id="${q.id}" type="button"><span class="question-order">${index+1}</span><div><strong>${escapeHtml(q.label)}${q.is_required?' *':''}</strong><small>${escapeHtml(questionTypeNames[q.question_type]||q.question_type)}${q.help_text?' · '+escapeHtml(q.help_text):''}</small></div><span class="question-flags">${q.is_protected?'<em>Protected</em>':''}${q.is_active?'':'<em class="off">Hidden</em>'}</span></button>`).join(''):empty('No questions yet','Add the details you would like couples to complete.');document.querySelectorAll('[data-question-id]').forEach(button=>button.onclick=()=>openQuestion(rows.find(q=>q.id===button.dataset.questionId)))}
function enquiryEmbedCode(form){const url=form.public_url,parsed=new URL(url),frameId=`ivory-enquiry-${dashboard.tenant.slug}`;return `<iframe id="${frameId}" data-ivory-enquiry src="${url}?embed=1" title="Enquiry form for ${escapeHtml(dashboard.tenant.display_name)}" loading="lazy" style="width:100%;min-height:1050px;border:0;border-radius:18px;background:transparent" referrerpolicy="strict-origin-when-cross-origin"></iframe>\n<script async src="${parsed.origin}/embed.js"></script>`}
function enquiryButtonCode(form){return `<a href="${form.public_url}" target="_blank" rel="noopener" style="display:inline-block;padding:14px 22px;border-radius:10px;color:#fff;background:${dashboard.tenant.branding?.accent_colour||'#a9782e'};font:700 15px Arial,sans-serif;text-decoration:none">Enquire about your date</a>`}
function renderEnquirySharing(){const published=!!enquiryForm.is_published,url=enquiryForm.public_url,embedUrl=`${url}?embed=1`;$('#enquiry-direct-link').value=url;$('#enquiry-embed-code').value=enquiryEmbedCode(enquiryForm);$('#enquiry-preview').href=url;$('#preview-enquiry-embed').href=embedUrl;$('#share-status').textContent=published?'Published & ready':'Draft — publish first';$('#share-status').classList.toggle('live',published);['#copy-enquiry-link','#copy-enquiry-button','#copy-enquiry-embed'].forEach(selector=>$(selector).disabled=!published);$('#download-enquiry-qr').classList.toggle('disabled',!published);$('#download-enquiry-qr').setAttribute('aria-disabled',published?'false':'true');$('#preview-enquiry-embed').classList.toggle('disabled',!published);$('#enquiry-preview').classList.toggle('disabled',!published)}
async function copyShare(value,message){try{await navigator.clipboard.writeText(value);toast(message)}catch{toast('Your browser blocked copying. Select the code and copy it manually.',true)}}
async function loadEnquiryForm(){try{enquiryForm=await api('/api/studio/enquiry-form');$('#enquiry-heading').value=enquiryForm.heading;$('#enquiry-introduction').value=enquiryForm.introduction;$('#enquiry-submit-label').value=enquiryForm.submit_label;$('#enquiry-success').value=enquiryForm.success_message;$('#enquiry-published').checked=enquiryForm.is_published;renderQuestions();renderEnquirySharing()}catch(e){toast(e.message,true)}}
$('#copy-enquiry-link').onclick=()=>copyShare(enquiryForm.public_url,'Direct enquiry link copied.');$('#copy-enquiry-button').onclick=()=>copyShare(enquiryButtonCode(enquiryForm),'Website button code copied.');$('#copy-enquiry-embed').onclick=()=>copyShare(enquiryEmbedCode(enquiryForm),'Responsive website embed copied.');$('#download-enquiry-qr').onclick=event=>{if(!enquiryForm?.is_published){event.preventDefault();toast('Publish the enquiry form before downloading its QR code.',true)}};$('#preview-enquiry-embed').onclick=event=>{if(!enquiryForm?.is_published){event.preventDefault();toast('Publish the enquiry form before previewing it.',true)}};$('#enquiry-preview').onclick=event=>{if(!enquiryForm?.is_published){event.preventDefault();toast('Publish the enquiry form before previewing it.',true)}};
$('#enquiry-form').onsubmit=async e=>{e.preventDefault();const data={heading:$('#enquiry-heading').value,introduction:$('#enquiry-introduction').value,submit_label:$('#enquiry-submit-label').value,success_message:$('#enquiry-success').value,ask_partner_name:true,ask_phone:true,ask_venue:true,ask_package_interest:true,ask_message:true,is_published:$('#enquiry-published').checked};try{enquiryForm=await api('/api/studio/enquiry-form',{method:'PUT',body:JSON.stringify(data)});dashboard=await api('/api/studio/dashboard');render();renderQuestions();renderEnquirySharing();toast(data.is_published?'Enquiry form saved, published and ready to share.':'Enquiry form saved as a private draft.')}catch(err){$('#enquiry-error').textContent=err.message}};
function toggleQuestionOptions(){const choice=['single_choice','multiple_choice'].includes($('#question-type').value);$('#question-options-wrap').classList.toggle('hidden',!choice)}
function openQuestion(question){$('#question-form').reset();$('#question-id').value=question?.id||'';$('#question-dialog-title').textContent=question?'Edit question':'Add a question';$('#question-label').value=question?.label||'';$('#question-help').value=question?.help_text||'';$('#question-type').value=question?.question_type||'short_text';$('#question-type').disabled=!!question?.is_protected;$('#question-options').value=(question?.options||[]).join('\n');$('#question-required').checked=!!question?.is_required;$('#question-active').checked=question?question.is_active:true;$('#delete-question').classList.toggle('hidden',!question||question.is_protected);$('#question-error').textContent='';toggleQuestionOptions();$('#question-dialog').showModal()}
$('#new-question').onclick=()=>openQuestion();$('#question-type').onchange=toggleQuestionOptions;
$('#question-form').onsubmit=async event=>{event.preventDefault();const id=$('#question-id').value,existing=(enquiryForm.questions||[]).find(q=>q.id===id),data={label:$('#question-label').value,help_text:$('#question-help').value,question_type:$('#question-type').value,is_required:$('#question-required').checked,is_active:$('#question-active').checked,options:$('#question-options').value.split('\n'),sort_order:existing?.sort_order??(enquiryForm.questions||[]).length};try{await api(`/api/studio/enquiry-form/questions${id?'/'+id:''}`,{method:id?'PATCH':'POST',body:JSON.stringify(data)});$('#question-dialog').close();await loadEnquiryForm();toast(id?'Question updated.':'Question added.')}catch(error){$('#question-error').textContent=error.message}};
$('#delete-question').onclick=async()=>{const id=$('#question-id').value;if(!id)return;try{await api(`/api/studio/enquiry-form/questions/${id}`,{method:'DELETE'});$('#question-dialog').close();await loadEnquiryForm();toast('Question removed.')}catch(error){$('#question-error').textContent=error.message}};

function verified(value){return value?'Connected':'Not tested'}
async function loadMailbox(){try{mailbox=await api('/api/studio/mailbox');$('#mail-from-name').value=mailbox.from_name||dashboard.tenant.display_name;$('#mail-address').value=mailbox.email_address;['smtp','imap'].forEach(type=>{for(const key of ['host','port','security','username'])$(`#${type}-${key}`).value=mailbox[`${type}_${key}`];$(`#${type}-status`).textContent=verified(mailbox[`${type}_verified_at`]);$(`#${type}-status`).classList.toggle('connected',!!mailbox[`${type}_verified_at`]);$(`#${type}-password-note`).textContent=mailbox[`${type}_has_password`]?'Password saved securely. Leave blank to keep it.':'Required when first connecting.'})}catch(e){toast(e.message,true)}}
function mailboxPayload(){return {from_name:$('#mail-from-name').value,email_address:$('#mail-address').value,smtp_host:$('#smtp-host').value,smtp_port:Number($('#smtp-port').value),smtp_security:$('#smtp-security').value,smtp_username:$('#smtp-username').value,smtp_password:$('#smtp-password').value,imap_host:$('#imap-host').value,imap_port:Number($('#imap-port').value),imap_security:$('#imap-security').value,imap_username:$('#imap-username').value,imap_password:$('#imap-password').value}}
async function saveMailbox(){mailbox=await api('/api/studio/mailbox',{method:'PUT',body:JSON.stringify(mailboxPayload())});$('#smtp-password').value='';$('#imap-password').value='';dashboard=await api('/api/studio/dashboard');render();return mailbox}
$('#mailbox-form').onsubmit=async e=>{e.preventDefault();try{await saveMailbox();await loadMailbox();toast('Email connection saved securely. Nothing has been sent.')}catch(err){$('#mailbox-error').textContent=err.message}};
async function testMail(type){const button=$(`#test-${type}`),status=$(`#${type}-status`);button.disabled=true;status.textContent='Testing…';try{await saveMailbox();await api(`/api/studio/mailbox/test/${type}`,{method:'POST'});await loadMailbox();toast(`${type.toUpperCase()} connection verified.`)}catch(err){status.textContent='Check details';status.classList.remove('connected');$('#mailbox-error').textContent=err.message}finally{button.disabled=false}}
$('#test-smtp').onclick=()=>testMail('smtp');$('#test-imap').onclick=()=>testMail('imap');

async function loadEnquiries(){try{const rows=await api('/api/studio/enquiries');$('#enquiry-list').innerHTML=rows.length?rows.map(row=>`<article class="panel enquiry-card"><div class="enquiry-avatar">${escapeHtml(initials([row.first_name,row.partner_name].filter(Boolean).join(' & ')))}</div><div class="enquiry-main"><span>${row.event_date?formatDate(row.event_date):'Date not supplied'}</span><h2>${escapeHtml(row.first_name)}${row.partner_name?' & '+escapeHtml(row.partner_name):''}</h2><p>${escapeHtml(row.venue||'Venue not supplied')} ${row.package_interest?'· '+escapeHtml(row.package_interest):''}</p><small>${escapeHtml(row.email)}${row.phone?' · '+escapeHtml(row.phone):''}</small>${row.message?`<blockquote>${escapeHtml(row.message)}</blockquote>`:''}${row.answers?.length?`<dl class="enquiry-answers">${row.answers.map(item=>`<div><dt>${escapeHtml(item.label)}</dt><dd>${escapeHtml(item.answer)}</dd></div>`).join('')}</dl>`:''}<div class="card-actions">${row.status==='converted'?'<span class="journey-chip">Moved to Weddings</span>':`<button class="button primary convert-enquiry" data-enquiry="${row.id}">Start client journey</button>`}</div></div><em>${escapeHtml(row.status==='converted'?'In progress':'New')}</em></article>`).join(''):empty('No enquiries yet','Publish your enquiry form when it is ready. New submissions will appear here immediately.');document.querySelectorAll('.convert-enquiry').forEach(button=>button.onclick=async()=>{button.disabled=true;button.textContent='Preparing…';try{const journey=await api(`/api/studio/enquiries/${button.dataset.enquiry}/convert`,{method:'POST',body:JSON.stringify({title:''})});dashboard=await api('/api/studio/dashboard');render();await showSection('weddings');await openJourney(journey.id);toast('The couple now has a clear wedding journey.')}catch(error){toast(error.message,true);button.disabled=false;button.textContent='Start client journey'}})}catch(e){toast(e.message,true)}}

function formatDate(value){return value?new Intl.DateTimeFormat('en-GB',{weekday:'long',day:'numeric',month:'long',year:'numeric'}).format(new Date(value+'T12:00:00')):'Date to be confirmed'}
function statusLabel(value){return ({quote_preparation:'Preparing quote',awaiting_quote_acceptance:'Awaiting acceptance',quote_accepted:'Quote accepted',confirmed:'Confirmed',completed:'Completed',cancelled:'Cancelled'})[value]||value.replaceAll('_',' ')}
async function loadWeddings(){try{weddings=await api('/api/studio/bookings');$('#journey-workspace').classList.add('hidden');$('#wedding-list').classList.remove('hidden');$('#wedding-list').innerHTML=weddings.length?weddings.map(row=>`<button class="panel wedding-card" data-wedding="${row.id}"><span class="wedding-date"><b>${row.event_date?new Date(row.event_date+'T12:00:00').getDate():'—'}</b><small>${row.event_date?new Intl.DateTimeFormat('en-GB',{month:'short'}).format(new Date(row.event_date+'T12:00:00')):'TBC'}</small></span><div><span>${escapeHtml(formatDate(row.event_date))}</span><h2>${escapeHtml(row.title)}</h2><p>${escapeHtml(row.venue||'Venue to be confirmed')}</p></div><em class="journey-chip">${escapeHtml(statusLabel(row.status))}</em><i>›</i></button>`).join(''):empty('No wedding journeys yet','Open an enquiry and choose “Start client journey”.');document.querySelectorAll('[data-wedding]').forEach(button=>button.onclick=()=>openJourney(button.dataset.wedding))}catch(error){toast(error.message,true)}}

async function openJourney(id){try{activeJourney=await api(`/api/studio/bookings/${id}/journey`);if(!packages.length)await loadPackages();if(!workflows.length)workflows=await api('/api/studio/workflows');$('#wedding-list').classList.add('hidden');const workspace=$('#journey-workspace');workspace.classList.remove('hidden');const j=activeJourney,invoice=j.invoices.find(item=>item.status!=='void'),accepted=!!j.accepted_quote?.accepted_at,quote=j.quote||{};workspace.innerHTML=`<button id="back-weddings" class="text-button">← All weddings</button><header class="journey-hero panel"><div><span class="eyebrow">${escapeHtml(statusLabel(j.status))}</span><h1>${escapeHtml(j.title)}</h1><p>${escapeHtml(formatDate(j.event_date))} · ${escapeHtml(j.venue||'Venue to be confirmed')}</p></div><div class="journey-hero-actions"><button id="copy-portal" class="button quiet">Copy couple link</button>${!['completed','cancelled'].includes(j.status)?'<button id="complete-wedding" class="button primary">Wedding complete</button><button id="cancel-wedding" class="button danger">Cancel booking</button>':j.status==='completed'?'<span class="complete-stamp">✓ Completed</span>':'<span class="journey-chip">Cancelled</span>'}</div></header><div class="journey-grid"><section class="journey-main">${accepted?acceptedQuotePanel(j):quoteBuilder(j)}${invoice?invoicePanel(invoice):''}${contractPanel(j)}${submittedFormsPanel(j)}</section><aside class="journey-side">${couplePanel(j)}${workflowPanel(j)}${calendarPanel(j)}</aside></div>`;wireJourney()}catch(error){toast(error.message,true)}}
function acceptedQuotePanel(j){const q=j.accepted_quote,invoice=j.invoices.find(item=>item.status!=='void'),canAmend=invoice&&invoice.status!=='paid';return `<article class="panel journey-panel"><header><span class="journey-number">1</span><div><span class="eyebrow">ACCEPTED QUOTE</span><h2>${escapeHtml(q.package?.name||'Chosen package')}</h2></div><strong>${money(q.total_pence||0)}</strong></header><div class="snapshot-list">${(q.line_items||[]).map(item=>`<div><span>${escapeHtml(item.label)}</span><b>${money(item.price_pence)}</b></div>`).join('')}</div><p class="record-note">Accepted by ${escapeHtml(q.accepted_by||'the couple')} on ${new Date(q.accepted_at).toLocaleString('en-GB')}. ${j.quote_revisions?.length?j.quote_revisions.length+' audited amendment'+(j.quote_revisions.length===1?'':'s')+' recorded.':'The original snapshot is safely preserved.'}</p>${canAmend?`<details class="quote-amend"><summary>Add something before full payment</summary><div><label>Description<input id="amend-label" placeholder="Complimentary wedding album"></label><label>Price (£)<input id="amend-price" type="number" min="0" step="0.01" value="0"></label><label class="wide-amend">Reason for the audit trail<input id="amend-reason" placeholder="Promotional album agreed with couple"></label><button id="amend-quote" class="button quiet">Add to quote and invoice</button></div></details>`:'<p class="record-note">Paid in full — this quote and invoice are now locked.</p>'}</article>`}
function quoteBuilder(j){const chosenPackages=new Set((j.quote?.packages||[]).map(item=>item.id)),chosenExtras=new Set((j.quote?.add_ons||[]).map(item=>item.id)),custom=j.quote?.custom_items||[],sent=j.quote?.status==='sent';return `<article class="panel journey-panel quote-builder"><header><span class="journey-number">1</span><div><span class="eyebrow">QUOTE</span><h2>Give them a clear choice</h2></div><em>${sent?'Sent':j.quote?.status==='draft'?'Draft saved':j.quote?.status==='expired'?'Expired':'Not started'}</em></header><p class="panel-intro">Tick the packages and extras you want to offer. Nothing ordinary is pre-selected for the couple.</p><h3>Packages offered</h3><div class="choice-cards">${packages.filter(item=>item.is_active).map(item=>`<label><input class="quote-package" type="checkbox" value="${item.id}" ${chosenPackages.has(item.id)?'checked':''}><span><strong>${escapeHtml(item.name)}</strong><small>${money(item.price_pence)} · ${money(item.booking_fee_pence)} booking fee</small></span></label>`).join('')}</div><h3>Extras offered</h3><div class="choice-cards compact">${addOns.filter(item=>item.is_active).map(item=>{const eligible=(item.eligible_package_ids||[]).map(id=>packages.find(p=>p.id===id)?.name).filter(Boolean);return `<label><input class="quote-addon" type="checkbox" value="${item.id}" ${chosenExtras.has(item.id)||item.selection_mode==='mandatory'?'checked':''} ${item.selection_mode==='mandatory'?'disabled':''}><span><strong>${escapeHtml(item.name)}</strong><small>${money(item.price_pence)}${item.selection_mode==='mandatory'?' · Required':''}${eligible.length?' · '+escapeHtml(eligible.join(', ')):' · All packages'}</small></span></label>`}).join('')}</div><div class="custom-quote-head"><h3>Custom items or discounts</h3><button id="add-custom-quote-item" type="button" class="text-action">＋ Add item</button></div><div id="quote-custom-items">${custom.map(item=>quoteCustomItemRow(item)).join('')}</div><label class="journey-message">A personal note<textarea id="quote-message" rows="4">${escapeHtml(j.quote?.message||'')}</textarea></label><label class="quote-expiry">Quote expiry <small>Optional</small><input id="quote-expires" type="date" value="${escapeAttr(j.quote?.expires_on||'')}"></label><div class="panel-actions"><button id="save-quote" class="button quiet">Save quote draft</button><button id="review-quote-email" class="button primary">${sent?'Save & review resend':'Save & review email'}</button></div><p class="record-note">Saving sends nothing. You will review the exact email before it is sent.</p></article>`}
function quoteCustomItemRow(item={}){return `<div class="quote-custom-row"><input class="quote-custom-label" value="${escapeAttr(item.label||'')}" maxlength="180" placeholder="For example: Extra hour or private discount"><label>£ <input class="quote-custom-price" type="number" step="0.01" value="${Number(item.price_pence||0)/100}"></label><button type="button" class="remove-custom-quote" aria-label="Remove item">×</button></div>`}
function quoteDraftPayload(){return {package_ids:[...document.querySelectorAll('.quote-package:checked')].map(item=>item.value),add_on_ids:[...document.querySelectorAll('.quote-addon:checked:not(:disabled)')].map(item=>item.value),custom_items:[...document.querySelectorAll('.quote-custom-row')].map(row=>({label:row.querySelector('.quote-custom-label').value.trim(),price_pence:pence(row.querySelector('.quote-custom-price').value)})).filter(item=>item.label),message:$('#quote-message').value,expires_on:$('#quote-expires').value||null}}
function invoicePanel(invoice){return `<article class="panel journey-panel"><header><span class="journey-number">2</span><div><span class="eyebrow">INVOICE ${escapeHtml(invoice.number)}</span><h2>${escapeHtml(invoice.status==='paid'?'Paid in full':invoice.status==='part_paid'?'Part paid':'Awaiting payment')}</h2></div><strong>${money(invoice.outstanding_pence)} due</strong></header><div class="money-summary"><div><small>Invoice total</small><b>${money(invoice.total_pence)}</b></div><div><small>Received</small><b>${money(invoice.paid_pence)}</b></div><div><small>Balance due</small><b>${invoice.due_date?formatDate(invoice.due_date):'Not set'}</b></div></div>${invoice.payments.length?`<div class="payment-history">${invoice.payments.map(item=>`<div><span>${formatDate(item.paid_date)} · ${escapeHtml(item.payment_type.replaceAll('_',' '))}</span><strong>${money(item.amount_pence)}</strong></div>`).join('')}</div>`:''}<div class="panel-actions start"><a class="button quiet link-button" href="/api/studio/invoices/${invoice.id}/pdf">Download invoice PDF</a>${invoice.outstanding_pence?'<button class="button primary record-payment" data-invoice="'+invoice.id+'" data-outstanding="'+invoice.outstanding_pence+'">Record payment received</button>':'<span class="paid-stamp">✓ Invoice paid</span>'}</div></article>`}
function contractPanel(j){const c=j.contract;if(!c)return `<article class="panel journey-panel"><header><span class="journey-number">3</span><div><span class="eyebrow">AGREEMENT</span><h2>Issue the contract</h2></div></header><p class="panel-intro">The couple signs first. You then countersign, leaving both signatures permanently attached to the snapshot.</p><button id="issue-contract" class="button quiet">Issue active agreement</button></article>`;return `<article class="panel journey-panel"><header><span class="journey-number">3</span><div><span class="eyebrow">AGREEMENT</span><h2>${escapeHtml(c.title)}</h2></div><em>${c.supplier_signed_at?'Complete':c.client_signed_at?'Needs your signature':'Awaiting couple'}</em></header><div class="signature-grid"><div><small>Couple</small><strong>${c.client_signed_at?'✓ '+escapeHtml(c.client_name):'Not signed yet'}</strong></div><div><small>Photographer</small><strong>${c.supplier_signed_at?'✓ '+escapeHtml(c.supplier_name):'Not signed yet'}</strong></div></div><div class="panel-actions start"><a class="button quiet link-button" href="/api/studio/bookings/${j.id}/contract/pdf">Download agreement PDF</a>${c.client_signed_at&&!c.supplier_signed_at?'<button id="countersign-contract" class="button primary">Countersign agreement</button>':''}</div></article>`}
function submittedFormsPanel(j){if(!j.questionnaires?.length)return '';return `<article class="panel journey-panel"><header><span class="journey-number">4</span><div><span class="eyebrow">COMPLETED FORMS</span><h2>Answers ready for you</h2></div></header><div class="snapshot-list">${j.questionnaires.map(form=>`<div><span>${escapeHtml(form.form_type.replaceAll('_',' '))}<small> · ${new Date(form.submitted_at).toLocaleString('en-GB')}</small></span><a class="text-action" href="/api/studio/bookings/${j.id}/questionnaires/${form.form_type}/pdf">Download PDF</a></div>`).join('')}</div></article>`}
function couplePanel(j){return `<article class="panel side-card"><span class="eyebrow">COUPLE</span><h3>${escapeHtml(j.title)}</h3><p>${escapeHtml(j.client?.email||'')}<br>${escapeHtml(j.client?.phone||'No telephone number')}</p><a href="mailto:${escapeHtml(j.client?.email||'')}">Write an email</a></article>`}
function workflowPanel(j){const actions=j.workflow_actions||[],steps=workflows.flatMap(item=>item.steps||[]);return `<article class="panel side-card"><span class="eyebrow">WORKFLOW</span><h3>${actions.length} scheduled item${actions.length===1?'':'s'}</h3><p>${dashboard.tenant.automations_paused?'All automatic sending remains globally paused during proofing.':'Your configured modes are active.'}</p>${actions.slice(0,5).map(item=>`<div class="mini-status"><span>${escapeHtml(item.payload.name||'Workflow step')}</span><em>${escapeHtml(item.status)}</em></div>`).join('')}${steps.length?`<details class="couple-controls"><summary>Pause individual steps</summary>${steps.map(step=>{const paused=j.workflow_controls?.[step.id]?.paused===true;return `<button data-couple-step="${step.id}" data-paused="${paused?'true':'false'}"><span>${escapeHtml(step.name)}</span><em>${paused?'Paused':'Following '+(modeNames[step.mode]||'workflow')}</em></button>`}).join('')}</details>`:''}</article>`}
function calendarPanel(j){return `<article class="panel side-card"><span class="eyebrow">CALENDAR</span><h3>${escapeHtml((j.calendar?.status||'not ready').replaceAll('_',' '))}</h3><p>${escapeHtml(j.calendar?.last_error||'A secured booking will be kept in the connected calendar.')}</p>${!j.special_payment_arrangement?'<button id="special-arrangement" class="text-action">Record an agreed pay-later arrangement</button>':'<span class="journey-chip">Special arrangement recorded</span>'}</article>`}
function wireJourney(){$('#back-weddings').onclick=()=>loadWeddings();$('#copy-portal').onclick=async()=>{await navigator.clipboard.writeText(activeJourney.portal_url);toast('Secure couple link copied.')};$('#complete-wedding')?.addEventListener('click',async()=>{activeJourney=await api(`/api/studio/bookings/${activeJourney.id}/complete`,{method:'POST',body:JSON.stringify({completed:true})});await openJourney(activeJourney.id);toast('Wedding completed and safely archived.')});$('#cancel-wedding')?.addEventListener('click',cancelWedding);$('#save-quote')?.addEventListener('click',()=>saveJourneyQuote(false));$('#send-quote')?.addEventListener('click',()=>saveJourneyQuote(true));$('#amend-quote')?.addEventListener('click',amendQuote);document.querySelectorAll('.record-payment').forEach(button=>button.onclick=()=>openPayment(button.dataset.invoice,Number(button.dataset.outstanding)));$('#issue-contract')?.addEventListener('click',issueContract);$('#countersign-contract')?.addEventListener('click',countersignContract);$('#special-arrangement')?.addEventListener('click',setSpecialArrangement);document.querySelectorAll('[data-couple-step]').forEach(button=>button.onclick=async()=>{const pause=button.dataset.paused!=='true';await api(`/api/studio/bookings/${activeJourney.id}/workflow-control`,{method:'PUT',body:JSON.stringify({step_id:button.dataset.coupleStep,paused:pause})});await openJourney(activeJourney.id);toast(pause?'This step is paused for this couple.':'This couple now follows the step again.')})}
async function amendQuote(){try{await api(`/api/studio/bookings/${activeJourney.id}/quote/amend`,{method:'POST',body:JSON.stringify({label:$('#amend-label').value,price_pence:pence($('#amend-price').value),reason:$('#amend-reason').value})});await openJourney(activeJourney.id);toast('The quote and invoice were updated with an audit record.')}catch(error){toast(error.message,true)}}
async function refreshActiveJourney(){if(activeJourney?.is_provisional&&window.openEnquiryWorkspaceV56&&window.activeEnquiryId)return window.openEnquiryWorkspaceV56(window.activeEnquiryId);return openJourney(activeJourney.id)}
async function saveJourneyQuote(review=false){try{activeJourney=await api(`/api/studio/bookings/${activeJourney.id}/quote`,{method:'PUT',body:JSON.stringify(quoteDraftPayload())});if(review)return openQuoteEmailReview();toast('Quote draft saved. Nothing has been emailed.');await refreshActiveJourney()}catch(error){toast(error.message,true)}}
async function openQuoteEmailReview(){try{const preview=await api(`/api/studio/bookings/${activeJourney.id}/quote/email-preview`);openWorkDialog('Review quote email','NOTHING SENDS UNTIL YOU CONFIRM',`<div class="email-review"><label>To<input value="${escapeAttr(preview.recipient)}" readonly></label><label>Subject<input id="quote-email-subject" value="${escapeAttr(preview.subject)}" required></label><label>Message<textarea id="quote-email-body" rows="13" required>${escapeHtml(preview.body)}</textarea></label><label>Secure quote link<input value="${escapeAttr(preview.portal_url)}" readonly></label><p class="helper">Personal changes apply to this couple only. Your saved master template remains unchanged.</p></div>`,async dialog=>{await api(`/api/studio/bookings/${activeJourney.id}/quote/send`,{method:'POST',body:JSON.stringify({subject:dialog.querySelector('#quote-email-subject').value.trim(),body:dialog.querySelector('#quote-email-body').value.trim()})});toast('Quote email sent successfully.');await refreshActiveJourney()},'Send quote now')}catch(error){toast(error.message,true)}}
function openPayment(invoiceId,outstanding){$('#payment-form').reset();$('#payment-invoice-id').value=invoiceId;$('#payment-amount').value=(outstanding/100).toFixed(2);$('#payment-date').value=new Date().toISOString().slice(0,10);$('#payment-error').textContent='';$('#payment-dialog').showModal()}
$('#payment-form').onsubmit=async event=>{event.preventDefault();try{await api(`/api/studio/invoices/${$('#payment-invoice-id').value}/payments`,{method:'POST',body:JSON.stringify({amount_pence:pence($('#payment-amount').value),paid_date:$('#payment-date').value,payment_type:$('#payment-type').value,reference:$('#payment-reference').value,notes:$('#payment-notes').value})});$('#payment-dialog').close();await openJourney(activeJourney.id);toast('Payment recorded and the couple’s balance updated.')}catch(error){$('#payment-error').textContent=error.message}};
async function issueContract(){try{const templates=await api('/api/studio/contract-templates'),template=templates.find(item=>item.is_active);if(!template)throw new Error('Create an active agreement template in Contracts & forms first.');await api(`/api/studio/bookings/${activeJourney.id}/contract`,{method:'POST',body:JSON.stringify({template_id:template.id})});await openJourney(activeJourney.id);toast('Agreement added to the couple’s secure portal.')}catch(error){toast(error.message,true)}}
async function countersignContract(){try{await api(`/api/studio/bookings/${activeJourney.id}/contract/countersign`,{method:'POST',body:JSON.stringify({full_name:dashboard.user.full_name,agreed:true})});await openJourney(activeJourney.id);toast('Agreement countersigned safely.')}catch(error){toast(error.message,true)}}

async function loadPayments(){try{weddings=await api('/api/studio/bookings');const rows=weddings.flatMap(w=>w.invoices.map(invoice=>({...invoice,wedding:w})));$('#payment-list').innerHTML=rows.length?rows.map(row=>`<button class="panel payment-row" data-payment-wedding="${row.wedding.id}"><div><span>${escapeHtml(row.number)} · ${escapeHtml(row.wedding.title)}</span><strong>${money(row.total_pence)}</strong><small>${row.due_date?'Due '+formatDate(row.due_date):'No balance date'}</small></div><div><em>${escapeHtml(row.status.replaceAll('_',' '))}</em><b>${money(row.outstanding_pence)} outstanding</b></div></button>`).join(''):empty('No invoices yet','An itemised invoice is created when a couple accepts a quote.');document.querySelectorAll('[data-payment-wedding]').forEach(button=>button.onclick=async()=>{await showSection('weddings');await openJourney(button.dataset.paymentWedding)})}catch(error){toast(error.message,true)}}

async function loadCalendar(){try{calendarData=await api('/api/studio/calendar');$('#calendar-title').textContent=calendarData.connected?`Connected as ${calendarData.google_account_email||'Google account'}`:'Not connected';$('#calendar-copy').textContent=calendarData.connected?`Using ${calendarData.calendar_name}. Secured weddings and availability blocks sync privately.`:calendarData.platform_configured?'Connect the photographer’s own Google account. Couples are never invited.':'Ivory Digital’s Google connection keys need adding before studios can connect.';$('#calendar-actions').innerHTML=calendarData.connected?'<button id="disconnect-calendar" class="button quiet">Disconnect</button>':`<button id="connect-calendar" class="button primary" ${calendarData.platform_configured?'':'disabled'}>Connect Google Calendar</button>`;$('#connect-calendar')?.addEventListener('click',async()=>{try{const result=await api('/api/studio/calendar/connect',{method:'POST'});location.href=result.authorization_url}catch(error){toast(error.message,true)}});$('#disconnect-calendar')?.addEventListener('click',async()=>{await api('/api/studio/calendar/disconnect',{method:'POST'});await loadCalendar();toast('Google Calendar disconnected.')});$('#date-block-list').innerHTML=calendarData.blocks.length?calendarData.blocks.map(block=>`<article class="panel date-block"><div><span>${formatDate(block.start_date)}${block.end_date!==block.start_date?' → '+formatDate(block.end_date):''}</span><h3>${escapeHtml(block.label)}</h3><p>${escapeHtml(block.notes||'No private note')}</p></div><div><em>${escapeHtml(block.calendar?.status||'pending')}</em><button data-remove-block="${block.id}" class="text-action">Remove</button></div></article>`).join(''):empty('No dates blocked','Holidays and unavailable periods will appear here.');document.querySelectorAll('[data-remove-block]').forEach(button=>button.onclick=async()=>{await api(`/api/studio/date-blocks/${button.dataset.removeBlock}`,{method:'DELETE'});await loadCalendar();toast('Blocked period removed.')})}catch(error){toast(error.message,true)}}
$('#date-block-form').onsubmit=async event=>{event.preventDefault();try{await api('/api/studio/date-blocks',{method:'POST',body:JSON.stringify({start_date:$('#block-start').value,end_date:$('#block-end').value,label:$('#block-label').value,notes:$('#block-notes').value})});event.target.reset();$('#block-label').value='Unavailable';await loadCalendar();toast('Dates blocked safely.')}catch(error){toast(error.message,true)}};
$('#sync-calendar').onclick=async()=>{try{await api('/api/studio/calendar/sync',{method:'POST'});await loadCalendar();toast('Calendar sync checked safely.')}catch(error){toast(error.message,true)}};

async function loadDocuments(){try{const [templates,forms]=await Promise.all([api('/api/studio/contract-templates'),api('/api/studio/questionnaire-templates')]),template=templates[0];questionnaireTemplates=forms;$('#contract-template-id').value=template?.id||'';$('#contract-template-name').value=template?.name||'Wedding photography agreement';$('#contract-template-body').value=template?.body||'';renderQuestionnaireEditor()}catch(error){toast(error.message,true)}}
$('#contract-template-form').onsubmit=async event=>{event.preventDefault();const id=$('#contract-template-id').value;try{const saved=await api(`/api/studio/contract-templates${id?'/'+id:''}`,{method:id?'PUT':'POST',body:JSON.stringify({name:$('#contract-template-name').value,body:$('#contract-template-body').value,is_active:true})});$('#contract-template-id').value=saved.id;toast('Agreement template saved with a new version.')}catch(error){toast(error.message,true)}};
const questionnaireTypeNames={short_text:'Short answer',long_text:'Long answer',email:'Email',phone:'Telephone',number:'Number',date:'Date',time:'Time',yes_no:'Yes / No',single_choice:'Choose one',multiple_choice:'Choose several'};
function activeQuestionnaire(){return questionnaireTemplates.find(item=>item.form_type===activeQuestionnaireType)}
function renderQuestionnaireEditor(){document.querySelectorAll('[data-questionnaire-type]').forEach(button=>button.classList.toggle('active',button.dataset.questionnaireType===activeQuestionnaireType));const form=activeQuestionnaire();if(!form){$('#questionnaire-editor').innerHTML='<div class="empty"><strong>This form is being prepared</strong></div>';return}const sections=[];(form.questions||[]).forEach((question,index)=>{let section=sections.find(item=>item.key===(question.section||'general'));if(!section){section={key:question.section||'general',title:question.section_title||'Your details',questions:[]};sections.push(section)}section.questions.push({...question,index})});$('#questionnaire-editor').innerHTML=`<form id="questionnaire-template-form" class="questionnaire-template-form"><div class="form-grid"><label>Form name<input id="questionnaire-name" value="${escapeHtml(form.name)}" required maxlength="160"></label><label class="check questionnaire-live"><input id="questionnaire-active" type="checkbox" ${form.is_active?'checked':''}> Available in couple portals</label><label class="wide-field">Warm introduction<textarea id="questionnaire-introduction" rows="3" maxlength="4000">${escapeHtml(form.introduction||'')}</textarea></label></div><div class="questionnaire-toolbar"><div><strong>${form.questions.length} questions</strong><small>Grouped into ${sections.length} clear section${sections.length===1?'':'s'}</small></div><div><button id="restore-questionnaire" type="button" class="button quiet">Restore complete starter</button><button id="add-questionnaire-question" type="button" class="button quiet">＋ Add question</button><button type="submit" class="button primary">Save form</button></div></div><div class="questionnaire-sections">${sections.map(section=>`<section><header><span>${escapeHtml(section.title)}</span><small>${section.questions.length} question${section.questions.length===1?'':'s'}</small></header>${section.questions.map(question=>`<article class="questionnaire-row"><span class="question-type-icon">${escapeHtml((questionnaireTypeNames[question.type]||'Text').slice(0,1))}</span><div><strong>${escapeHtml(question.label)}${question.required?' <i>Required</i>':''}</strong><small>${escapeHtml(questionnaireTypeNames[question.type]||question.type)}${question.help_text?' · '+escapeHtml(question.help_text):''}</small></div><div class="questionnaire-row-actions"><button type="button" title="Move up" data-question-move="${question.index}" data-direction="-1">↑</button><button type="button" title="Move down" data-question-move="${question.index}" data-direction="1">↓</button><button type="button" data-question-edit="${question.index}">Edit</button><button type="button" class="remove" data-question-remove="${question.index}">Remove</button></div></article>`).join('')}</section>`).join('')}</div><p id="questionnaire-template-error" class="error"></p></form>`;$('#questionnaire-template-form').onsubmit=saveQuestionnaireTemplate;$('#add-questionnaire-question').onclick=()=>openQuestionnaireQuestion();$('#restore-questionnaire').onclick=restoreQuestionnaireStarter;document.querySelectorAll('[data-question-edit]').forEach(button=>button.onclick=()=>openQuestionnaireQuestion(Number(button.dataset.questionEdit)));document.querySelectorAll('[data-question-remove]').forEach(button=>button.onclick=()=>removeQuestionnaireQuestion(Number(button.dataset.questionRemove)));document.querySelectorAll('[data-question-move]').forEach(button=>button.onclick=()=>moveQuestionnaireQuestion(Number(button.dataset.questionMove),Number(button.dataset.direction)))}
document.querySelectorAll('[data-questionnaire-type]').forEach(button=>button.onclick=()=>{activeQuestionnaireType=button.dataset.questionnaireType;renderQuestionnaireEditor()});
async function saveQuestionnaireTemplate(event){event.preventDefault();const form=activeQuestionnaire();try{const saved=await api(`/api/studio/questionnaire-templates/${activeQuestionnaireType}`,{method:'PUT',body:JSON.stringify({form_type:activeQuestionnaireType,name:$('#questionnaire-name').value.trim(),introduction:$('#questionnaire-introduction').value.trim(),questions:form.questions,is_active:$('#questionnaire-active').checked})});questionnaireTemplates=questionnaireTemplates.map(item=>item.form_type===activeQuestionnaireType?saved:item);renderQuestionnaireEditor();toast(`${activeQuestionnaireType==='booking'?'Booking Questionnaire':'Final Wedding Timings'} saved.`)}catch(error){$('#questionnaire-template-error').textContent=error.message}}
function questionSectionKey(title){return title.toLowerCase().normalize('NFKD').replace(/[\u0300-\u036f]/g,'').replace(/[^a-z0-9]+/g,'_').replace(/^_+|_+$/g,'').slice(0,50)||'general'}
function toggleQuestionnaireOptions(){const kind=$('#questionnaire-question-type').value;$('#questionnaire-options-wrap').classList.toggle('hidden',!['single_choice','multiple_choice'].includes(kind))}
function openQuestionnaireQuestion(index=null){const form=activeQuestionnaire(),question=index===null?null:form.questions[index],last=form.questions.at(-1);$('#questionnaire-question-form').reset();$('#questionnaire-question-index').value=index===null?'':String(index);$('#questionnaire-dialog-title').textContent=question?'Edit question':'Add a question';$('#questionnaire-question-label').value=question?.label||'';$('#questionnaire-question-type').value=question?.type||'short_text';$('#questionnaire-section-title').value=question?.section_title||last?.section_title||'Your details';$('#questionnaire-question-help').value=question?.help_text||'';$('#questionnaire-question-placeholder').value=question?.placeholder||'';$('#questionnaire-question-options').value=(question?.options||[]).join('\n');$('#questionnaire-question-required').checked=!!question?.required;$('#questionnaire-question-error').textContent='';toggleQuestionnaireOptions();$('#questionnaire-dialog').showModal()}
$('#questionnaire-question-type').onchange=toggleQuestionnaireOptions;
$('#questionnaire-question-form').onsubmit=event=>{event.preventDefault();const form=activeQuestionnaire(),raw=$('#questionnaire-question-index').value,index=raw===''?null:Number(raw),old=index===null?null:form.questions[index],title=$('#questionnaire-section-title').value.trim(),kind=$('#questionnaire-question-type').value,options=$('#questionnaire-question-options').value.split('\n').map(value=>value.trim()).filter(Boolean);if(['single_choice','multiple_choice'].includes(kind)&&options.length<2){$('#questionnaire-question-error').textContent='Add at least two answer choices.';return}const question={id:old?.id||`custom_${Date.now().toString(36)}`,label:$('#questionnaire-question-label').value.trim(),type:kind,required:$('#questionnaire-question-required').checked,help_text:$('#questionnaire-question-help').value.trim(),placeholder:$('#questionnaire-question-placeholder').value.trim(),section:old?.section_title===title?old.section:questionSectionKey(title),section_title:title,options};if(index===null)form.questions.push(question);else form.questions[index]=question;$('#questionnaire-dialog').close();renderQuestionnaireEditor()};
function moveQuestionnaireQuestion(index,direction){const questions=activeQuestionnaire().questions,next=index+direction;if(next<0||next>=questions.length)return;[questions[index],questions[next]]=[questions[next],questions[index]];renderQuestionnaireEditor()}
function removeQuestionnaireQuestion(index){const question=activeQuestionnaire().questions[index];if(!confirm(`Remove “${question.label}” from this form? Existing submitted forms keep their original snapshot.`))return;activeQuestionnaire().questions.splice(index,1);renderQuestionnaireEditor()}
async function restoreQuestionnaireStarter(){if(!confirm('Replace this draft with the complete Ivory Digital starter form? Existing submitted forms and PDFs will not change.'))return;try{const restored=await api(`/api/studio/questionnaire-templates/${activeQuestionnaireType}/starter`,{method:'POST'});questionnaireTemplates=questionnaireTemplates.map(item=>item.form_type===activeQuestionnaireType?restored:item);renderQuestionnaireEditor();toast('Complete starter questions restored.')}catch(error){toast(error.message,true)}}

const helpContextNames={home:'Studio home',enquiries:'Enquiries',weddings:'Weddings',payments:'Payments',calendar:'Calendar & availability',documents:'Contracts & forms',brand:'Business & brand',enquiry:'Enquiry form',packages:'Packages & pricing',workflow:'Emails & workflow',mailbox:'Email connection'};
const guidedTours={
  home:[['.hero','Your Studio at a glance','This shows how far through setup you are. Nothing here sends a message to a couple.'],['.setup-panel','Your setup checklist','Work through these once. You can return and change any completed section later.'],['.calm-panel','The safety promise','Automatic messages remain safely paused while your business is prepared and proofed.']],
  enquiries:[['#enquiries-section .section-head','New conversations','Every enquiry arrives here first with the date, venue and answers together.'],['#enquiry-list','Prepare and send the quote here','Open an enquiry to build its quote, review the exact email and send it. It stays in Enquiries until it is booked.']],
  weddings:[['#weddings-section .section-head','Every couple in one place','Open a wedding to see the quote, invoice, agreement, forms and workflow together.'],['#wedding-list','Choose a wedding','The date, venue and current stage make it easy to find the right couple.'],['#journey-workspace:not(.hidden)','The complete client journey','When a wedding is open, each stage appears in order with the private controls alongside it.']],
  payments:[['#payments-section .safety-note','Payments stay honest','Only record money after you have actually received it.'],['#payment-list','Invoices and balances','Open any invoice to see its full wedding journey and record a payment.']],
  calendar:[['.calendar-connect','Your own Google account','Each photographer connects their own calendar. Couples are never invited to its private events.'],['#date-block-form','Block time away','Block one day or a whole holiday period so the dates are unavailable.'],['#date-block-list','Your unavailable dates','Every manual block and its calendar status appears here.']],
  documents:[['#contract-template-form','Your agreement','Write the terms once. Each issued contract keeps a fixed snapshot and both signatures.'],['.forms-panel','Complete couple forms','Choose either form, then add, edit and reorder questions in clear sections. Every submitted form keeps its original snapshot.'],['#questionnaire-editor','Make every question your own','Choose the answer type, add helpful wording and decide which answers are required. The complete starter can always be restored safely.']],
  brand:[['#brand-form','Your business details','Set the name, colour and welcome that couples see.'],['.portal-preview','Live couple preview','This gives you an immediate feel for your branded private client area.']],
  enquiry:[['#enquiry-share','Share it anywhere','Copy a direct link, a ready-made website button, a responsive embed or a downloadable QR code.'],['#enquiry-form','Your first hello','Write the welcome and deliberately publish the form only when it is ready.'],['.question-builder','Ask what matters','Protected essentials stay safe while your own questions can be added or edited.'],['#enquiry-preview','Preview before publishing','Open the real couple view without submitting an enquiry.']],
  packages:[['#package-list','Your main services','Set the price, booking fee, balance timing and everything included.'],['#addon-list','Optional extras','Albums and extra coverage begin unselected unless there is a genuine mandatory charge.'],['#new-package','Add another package','Create as many clear choices as your business needs.']],
  workflow:[['.paused-banner','Safe while you build','The master pause prevents automatic delivery during setup and proofing.'],['#workflow-steps','Your journey in order','Every step has its own trigger, timing and delivery mode.'],['#new-step','Add your own step','Create a private task, a review-first message or an automatic email. New steps begin disabled.']],
  mailbox:[['#mailbox-form .server-block:first-of-type','Outgoing email','SMTP lets Studio send from the photographer’s own professional address.'],['#mailbox-form .server-block:nth-of-type(2)','Incoming email','IMAP lets Studio verify and organise replies without changing workflow safety.'],['#mailbox-form>button[type="submit"]','Save safely','Saving or testing the mailbox never starts automatic messages.']]
};

function helpSuggestionHtml(article){return `<button class="help-suggestion" type="button" data-help-question="${escapeHtml(article.title)}"><span>${escapeHtml(article.title)}</span><i>›</i></button>`}
function renderHelpSuggestions(rows){$('#help-suggestions').innerHTML=(rows||[]).map(helpSuggestionHtml).join('')||'<p class="record-note">Ask anything about this part of your Studio.</p>';document.querySelectorAll('[data-help-question]').forEach(button=>button.onclick=()=>askHelp(button.dataset.helpQuestion))}
async function loadHelp(clearAnswer=true){$('#help-context-name').textContent=helpContextNames[currentSection]||'Your Studio';$('#start-page-tour').disabled=!(guidedTours[currentSection]||[]).length;try{const result=await api(`/api/studio/help/articles?context=${encodeURIComponent(currentSection)}`);helpCatalog=result.articles||[];renderHelpSuggestions(result.suggestions)}catch(error){renderHelpSuggestions([]);toast(error.message,true)}if(clearAnswer){$('#help-answer').classList.add('hidden');$('#help-answer').innerHTML=''}}
async function openHelp(){closeMenu();$('#help-drawer').classList.add('open');$('#help-drawer').setAttribute('aria-hidden','false');$('#help-scrim').classList.remove('hidden');document.body.style.overflow='hidden';await loadHelp();setTimeout(()=>$('#help-question').focus(),180)}
function closeHelp(){ $('#help-drawer').classList.remove('open');$('#help-drawer').setAttribute('aria-hidden','true');$('#help-scrim').classList.add('hidden');document.body.style.overflow=''}
function answerParagraphs(value){return String(value||'').split(/\n\s*\n/).filter(Boolean).map(part=>`<p>${escapeHtml(part)}</p>`).join('')}
async function askHelp(question){const value=String(question||$('#help-question').value).trim();if(!value)return;$('#help-question').value=value;const answer=$('#help-answer');answer.classList.remove('hidden');answer.innerHTML='<div class="answer-mark">ID</div><h3>Let me check that…</h3><p>Finding the clearest answer for this part of your Studio.</p>';try{const result=await api('/api/studio/help/ask',{method:'POST',body:JSON.stringify({question:value,context:currentSection})});const article=result.article;const title=article?.title||(result.matched?'Here’s what to do':'I need a little more detail');let actions='';if(article?.action_route)actions+=`<button class="answer-primary" type="button" data-help-route="${escapeHtml(article.action_route)}">${escapeHtml(article.action_label||'Open the right screen')}</button>`;if(article?.tour_key&&guidedTours[article.action_route||currentSection])actions+=`<button type="button" data-help-tour="${escapeHtml(article.action_route||currentSection)}">Show me step by step</button>`;if(!result.matched||!actions)actions+=`<a href="mailto:${escapeHtml(result.support_email||'sales@ivorydigital.uk')}">Contact Ivory Digital</a>`;answer.innerHTML=`<div class="answer-mark">ID</div><h3>${escapeHtml(title)}</h3>${answerParagraphs(result.answer)}<div class="answer-actions">${actions}<button type="button" data-helpful>That helped ✓</button></div>`;answer.querySelector('[data-help-route]')?.addEventListener('click',async event=>{closeHelp();await showSection(event.currentTarget.dataset.helpRoute)});answer.querySelector('[data-help-tour]')?.addEventListener('click',event=>startTour(event.currentTarget.dataset.helpTour));answer.querySelector('[data-helpful]')?.addEventListener('click',event=>{event.currentTarget.textContent='Thank you — glad it helped';event.currentTarget.disabled=true});renderHelpSuggestions(result.suggestions);answer.scrollIntoView({behavior:'smooth',block:'start'})}catch(error){answer.innerHTML=`<div class="answer-mark">ID</div><h3>I could not open the guide</h3><p>${escapeHtml(error.message)}</p><div class="answer-actions"><a href="mailto:sales@ivorydigital.uk">Contact Ivory Digital</a></div>`}}

function visibleTourSteps(key){return (guidedTours[key]||[]).map(([selector,title,copy])=>({element:document.querySelector(selector),title,copy})).filter(step=>step.element&&!step.element.classList.contains('hidden')&&step.element.getClientRects().length)}
function startTour(key=currentSection){const steps=visibleTourSteps(key);if(!steps.length){toast('Open that screen first, then start its tour.',true);return}closeHelp();tourSteps=steps;tourIndex=0;$('#tour-overlay').classList.remove('hidden');document.body.style.overflow='hidden';showTourStep()}
function showTourStep(){const step=tourSteps[tourIndex];if(!step){endTour();return}step.element.scrollIntoView({behavior:'smooth',block:'center'});setTimeout(()=>{const rect=step.element.getBoundingClientRect(),pad=7,focus=$('#tour-focus'),card=$('#tour-card');focus.style.left=`${Math.max(8,rect.left-pad)}px`;focus.style.top=`${Math.max(8,rect.top-pad)}px`;focus.style.width=`${Math.min(innerWidth-16,rect.width+pad*2)}px`;focus.style.height=`${Math.min(innerHeight-16,rect.height+pad*2)}px`;$('#tour-count').textContent=`Step ${tourIndex+1} of ${tourSteps.length}`;$('#tour-title').textContent=step.title;$('#tour-copy').textContent=step.copy;$('#tour-next').textContent=tourIndex===tourSteps.length-1?'Finish':'Next';if(innerWidth>760){const cardHeight=card.offsetHeight||220;let top=rect.bottom+18;if(top+cardHeight>innerHeight-18)top=Math.max(18,rect.top-cardHeight-18);let left=Math.min(innerWidth-card.offsetWidth-18,Math.max(18,rect.left));card.style.top=`${top}px`;card.style.left=`${left}px`;card.style.bottom='auto'}},320)}
function endTour(){tourSteps=[];tourIndex=0;$('#tour-overlay').classList.add('hidden');document.body.style.overflow=''}
$('#open-help').onclick=openHelp;$('#sidebar-help').onclick=openHelp;$('#close-help').onclick=closeHelp;$('#help-scrim').onclick=closeHelp;$('#help-form').onsubmit=event=>{event.preventDefault();askHelp()};$('#start-page-tour').onclick=()=>startTour(currentSection);$('#tour-next').onclick=()=>{tourIndex+=1;showTourStep()};$('#tour-exit').onclick=endTour;addEventListener('resize',()=>{if(!$('#tour-overlay').classList.contains('hidden'))showTourStep()});document.addEventListener('keydown',event=>{const writing=['INPUT','TEXTAREA','SELECT'].includes(document.activeElement?.tagName);if(event.key==='Escape'){if(!$('#tour-overlay').classList.contains('hidden'))endTour();else if($('#help-drawer').classList.contains('open'))closeHelp()}else if(event.key==='?'&&!writing&&!$('#studio-view').classList.contains('hidden')){event.preventDefault();openHelp()}});

window.startIvoryStudio=()=>{const invite=new URLSearchParams(location.search).get('invite');if(invite)showInvitation(invite);else openStudio()};
